            $variables_data[":" . $medicine->name . "_report_name:"] = $medicine->report_name;
            $variables_data[":" . $medicine->name . "_batch:"] = $medicine->batch;
            $variables_data[":" . $medicine->name . "_expiry:"] = $medicine->expiry;
