    public static function fillReportWithDates(string $html)
    {
        $variables_data = [
            ":date:" => Carbon::now()
                ->toDateString(),
            ":time:" => Carbon::now()
                ->addHour()
                ->toTimeString(),
            ":datetime:" => Carbon::now()
                ->addHour()
                ->toDateTimeString(),
        ];

        foreach ($variables_data as $variable => $variable_data) {
            $html = str_replace($variable, $variables_data[$variable] ?? '', $html);
        }

        return $html;
    }

    public static function sendSMS(string $message = '', $destination = null)
    {
        try {
            if (empty($destination)) {
                return false;
            }

            // Path to store a local copy of the WSDL
            $wsdlPath = storage_path('app/wsdl_cache/service.wsdl');
            $wsdlDir = dirname($wsdlPath);

            if (!file_exists($wsdlDir)) {
                mkdir($wsdlDir, 0775, true);
            }

            // Only fetch WSDL if it doesn't exist
            if (!file_exists($wsdlPath)) {
                $ch = curl_init('https://www.textapp.net/webservice/service.asmx?wsdl');
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
                curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false);
                $wsdlContent = curl_exec($ch);
                $curlError = curl_error($ch);
                curl_close($ch);

                if ($wsdlContent === false) {
                    \Log::channel('sms')->error('Failed to fetch WSDL: ' . $curlError);
                    return false;
                }

                file_put_contents($wsdlPath, $wsdlContent);
            }

            $context = stream_context_create([
                'ssl' => [
                    'verify_peer' => false,
                    'verify_peer_name' => false,
                    'allow_self_signed' => true,
                ],
            ]);

            $options = [
                'trace' => true,
                'exceptions' => true,
                'cache_wsdl' => WSDL_CACHE_NONE,
                'stream_context' => $context,
            ];

            $sc = new \SoapClient($wsdlPath, $options);

            $params = new \stdClass();
            $params->returnCSVString = false;
            $params->externalLogin = env('TEXTANYWHERE_USERNAME');
            $params->password = env('TEXTANYWHERE_PASSWORD');
            $params->clientBillingReference = now()->toDateString();
            $params->clientMessageReference = 'test';
            $params->originator = env('TEXTANYWHERE_ORIGINATOR');
            $params->destinations = $destination;
            $params->body = utf8_encode($message);
            $params->validity = 72;
            $params->characterSetID = 2;
            $params->replyMethodID = 4;
            $params->replyData = '';
            $params->statusNotificationUrl = '';

            $result = $sc->__soapCall('SendSMS', [$params]);
            \Log::channel('sms')->info('SMS Response: ' . $result->SendSMSResult);

            return true;

        } catch (\Exception $e) {
            \Log::channel('sms')->error('SMS Error: ' . $e->getMessage());
            return false;
        }
    }
    public static function getPatientParentTypeForSelect()
    {
        $patient_parent_types = config('constants.patient_parent_type');
        return $patient_parent_types;
    }

    public static function sendWhatsAppMessage($cell_number, $link)
    {
        $twilioSid = env('TWILIO_SID');
        $twilioToken = env('TWILIO_AUTH_TOKEN');
        $twilioWhatsAppNumber = env('TWILIO_WHATSAPP_NUMBER');
        $recipientNumber = 'whatsapp:' . $cell_number;
        $message = $link;

        $twilio = new Client($twilioSid, $twilioToken);

        try {
            $twilio->messages->create(
                $recipientNumber,
                [
                    "from" => $twilioWhatsAppNumber,
                    "body" => $message,
                ]
            );
            return response()->json(['message' => 'WhatsApp message sent successfully']);
        } catch (\Exception $e) {
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }
